/// The reference shapes of one kind.
pub fn of_kind(kind: AssetKind) -> impl Iterator<Item = &'static RefShape> {
    REFS.iter().filter(move |r| r.kind == kind)
}

/// One reference shape by kind and slug.
pub fn find(kind: AssetKind, slug: &str) -> Option<&'static RefShape> {
    of_kind(kind).find(|r| r.slug == slug)
}
